mapper.select:
SELECT i.id, i.tenant_id, i.dict_type_id, i.option_code, i.option_label, i.sort_no, i.status,
       i.created_at, i.updated_at, i.version
FROM sys_dictionary_item i
INNER JOIN sys_dictionary_type t
        ON t.id = i.dict_type_id AND t.tenant_id = i.tenant_id
WHERE i.tenant_id = #{tenantId}
  AND t.dict_code = #{dictCode}
  AND i.option_code = #{optionCode}
  AND t.status = 'ACTIVE'
  AND i.status = 'ACTIVE'

SELECT id, tenant_id, dict_code, dict_name, status, created_at, updated_at, version
FROM sys_dictionary_type
WHERE tenant_id = #{tenantId} AND dict_code = #{dictCode}

mapper.update:
UPDATE sys_dictionary_item
SET option_label = #{optionLabel}, sort_no = #{sortNo}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{version}

UPDATE sys_dictionary_item
SET status = #{toStatus}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = #{fromStatus}
